<div class="mt-5 flex flex-wrap items-end justify-between gap-4"><div><p class="eyebrow">VALIDACIÓN DEL PERÍODO</p><h1 class="page-title"><?= e($meses[(int) $periodo['mes']] . ' ' . $periodo['anio']) ?></h1><p class="page-description">Revisa los datos que forman parte de este período antes de aprobarlo.</p></div><span class="status-chip estado-<?= e($periodo['estado']) ?>"><?= e($estados[$periodo['estado']]) ?></span></div>

