<section class="panel mt-6"><div class="mb-5"><h2 class="section-title">Conexiones activas incluidas</h2><p class="mt-1 text-sm text-slate-500">Estas conexiones determinan el peso de cada zona en los resultados.</p></div><div class="overflow-x-auto"><table class="data-table min-w-[700px]"><caption class="sr-only">Conexiones activas del período seleccionado</caption><thead><tr><th>Sector</th><th>Zona de presión</th><th class="text-right">Conexiones activas</th><th>Estado</th><th>Observación</th></tr></thead><tbody><?php foreach ($conexiones as $conexion): ?><tr><td class="font-medium text-slate-800"><?= e($conexion['sector']) ?></td><td><?= e($conexion['zona_presion']) ?></td><td class="text-right font-semibold text-slate-800"><?= number_format((int) $conexion['cantidad']) ?></td><td><span class="badge"><?= e($conexion['estado_dato']) ?></span></td><td class="max-w-72 truncate" title="<?= e($conexion['observacion'] ?? '') ?>"><?= e($conexion['observacion'] ?? '—') ?></td></tr><?php endforeach; ?></tbody></table></div></section>
